shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/test/xchar-test.cc
+++ b/test/xchar-test.cc
@@ -440,6 +440,39 @@
   EXPECT_EQ(fmt::format(loc, "{:8L}", 1230.0), "   1~230");
 }

+TEST(locale_test, localized_double_alignment) {
+  auto loc = std::locale(std::locale(std::locale::classic(), new numpunct<char>()),
+                         new numpunct<wchar_t>());
+  EXPECT_EQ(std::string(14, ' ') + "0?295",
+            fmt::format(loc, "{:19.3Lf}", 0.295));
+  for (double value : {0.295, -0.295, 1.295, -119.921, 2194.139, -57.639,
+                       -5.980, -2.119, 0.0, -0.0, 0.000295, 0.9999}) {
+    auto s = fmt::format(loc, "{:.3Lf}", value);
+    auto padding = std::string(19 - s.size(), ' ');
+    EXPECT_EQ(padding + s, fmt::format(loc, "{:19.3Lf}", value));
+    EXPECT_EQ(s + padding, fmt::format(loc, "{:<19.3Lf}", value));
+    EXPECT_EQ(std::string(padding.size() / 2, ' ') + s +
+                  std::string((padding.size() + 1) / 2, ' '),
+              fmt::format(loc, "{:^19.3Lf}", value));
+    auto ws = fmt::format(loc, L"{:.3Lf}", value);
+    EXPECT_EQ(std::wstring(19 - ws.size(), L' ') + ws,
+              fmt::format(loc, L"{:19.3Lf}", value));
+  }
+  EXPECT_EQ("0000000?295", fmt::format(loc, "{:011.3Lf}", 0.295));
+  EXPECT_EQ("-000000?295", fmt::format(loc, "{:011.3Lf}", -0.295));
+  EXPECT_EQ("+000000?295", fmt::format(loc, "{:+011.3Lf}", 0.295));
+  EXPECT_EQ("     1?23456", fmt::format(loc, "{:12.6Lg}", 1.23456));
+  EXPECT_EQ(" 1?23456e+00", fmt::format(loc, "{:12.5Le}", 1.23456));
+  auto small_loc = std::locale(std::locale::classic(), new small_grouping<char>());
+  EXPECT_EQ("       1.295", fmt::format(small_loc, "{:12.3Lf}", 1.295));
+  EXPECT_EQ("      1,2.34", fmt::format(small_loc, "{:12.2Lf}", 12.34));
+  auto plain_loc = std::locale(std::locale::classic(), new no_grouping<char>());
+  EXPECT_EQ(std::string(14, ' ') + "0.295",
+            fmt::format(plain_loc, "{:19.3Lf}", 0.295));
+  EXPECT_EQ(std::string(14, ' ') + "0.295",
+            fmt::format(loc, "{:19.3f}", 0.295));
+}
+
 TEST(locale_test, format) {
   auto loc = std::locale(std::locale(), new numpunct<char>());
   EXPECT_EQ("1234567", fmt::format(std::locale(), "{:L}", 1234567));
PATCH
cmake -B build -S . && cmake --build build --parallel 4 --target xchar-test && build/bin/xchar-test --gtest_filter=locale_test.localized_double_alignment

